-- =============================================================================
-- V186 — OCCPL's rate zones as the customers' rate sheets price them (user, 2026-11-27). Generated, do not edit.
--
-- Companies OCCPL and OCCPL_COURIER, where V173 set up the Zone Tariff (a company without zone REST_OF_INDIA is skipped).
-- Before: PUNE, X_PUNE, MAHARASHTRA, X_MAHARASHTRA, VIDHARBHA, REST_OF_INDIA, NORTH_EAST.
-- After:  PUNE, X_PUNE, MAHARASHTRA, X_MAHARASHTRA, VIDHARBHA, METRO, WEST, CENTRAL, SOUTH, NORTH, EAST, NORTH_EAST.
--
-- Each pincode of the pincode master (V185's sheet) goes to one zone:
--   METRO        Mumbai 400001-400104, Delhi 110001-110999, Kolkata 700001-700160, Chennai 600001-600130, Bengaluru 560001-560999, Hyderabad 500001-500100 (Mumbai leaves MAHARASHTRA, Kolkata leaves the North East region)
--   PUNE … VIDHARBHA   the sheet's Region
--   Rest of India      the sheet's zone column: WEST, CENTRAL, SOUTH, NORTH
--   North East region  NORTH_EAST for Assam, Tripura, Meghalaya, Manipur, Arunachal Pradesh, Nagaland, Mizoram, Sikkim;
--                      EAST for the rest (West Bengal, Odisha, Bihar, Jharkhand, Andaman & Nicobar, Lakshadweep)
-- Pincodes per zone: PUNE 50, X_PUNE 12, MAHARASHTRA 130, X_MAHARASHTRA 999, VIDHARBHA 301, METRO 673, WEST 1114, CENTRAL 1032, SOUTH 6326, NORTH 4388, EAST 3182, NORTH_EAST 920.
--
-- 1. Backup: every row of the five Zone Tariff tables into backup_20261127_* (restore as V173 describes).
-- 2. Zones METRO, WEST, CENTRAL, SOUTH, NORTH, EAST added (From and To, like V173's).
-- 3. Places of all twelve zones (and REST_OF_INDIA) rebuilt the V173 way: a whole city when all its pincodes on file are
--    in one zone, else each pincode. Places added by hand in the app since V173 are replaced (they are in the backup).
-- 4. Rates follow: on every rate card of the company (its own and its business customers'), each REST_OF_INDIA lane and
--    charge rule is copied to METRO, WEST, CENTRAL, SOUTH and NORTH, and each NORTH_EAST one to EAST, so every price
--    stays what it was, except Mumbai (now METRO: the Rest of India rate instead of Maharashtra's) and Kolkata (the Rest
--    of India rate instead of North East's). Edit the METRO lanes on the card for metro prices.
-- 5. REST_OF_INDIA, its places, lanes and charge rules are removed (soft delete).
-- =============================================================================

SET @g = UNHEX('00000000000000000000000000000001');

-- 1. Backup ------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS backup_20261127_tariff_zones LIKE tariff_zones;
CREATE TABLE IF NOT EXISTS backup_20261127_tariff_zone_locations LIKE tariff_zone_locations;
CREATE TABLE IF NOT EXISTS backup_20261127_tariff_rate_cards LIKE tariff_rate_cards;
CREATE TABLE IF NOT EXISTS backup_20261127_tariff_rate_slabs LIKE tariff_rate_slabs;
CREATE TABLE IF NOT EXISTS backup_20261127_tariff_charge_rules LIKE tariff_charge_rules;

DROP TABLE IF EXISTS tmp_v186_co;
CREATE TABLE tmp_v186_co (company_id BINARY(16) NOT NULL PRIMARY KEY, roi_id BINARY(16) NOT NULL, ne_id BINARY(16) NULL) ENGINE = InnoDB;
SELECT c.company_id, roi.id,
       (SELECT ne.id FROM tariff_zones ne WHERE ne.company_id = c.company_id AND ne.code = 'NORTH_EAST' AND ne.deleted = FALSE LIMIT 1)
FROM companies c
JOIN tariff_zones roi ON roi.company_id = c.company_id AND roi.code = 'REST_OF_INDIA' AND roi.deleted = FALSE
WHERE c.company_code IN ('OCCPL', 'OCCPL_COURIER') AND c.deleted = FALSE;

-- 2. Zones ------------------------------------------------------------------------------------------------
DROP TABLE IF EXISTS tmp_v186_zone;
CREATE TABLE tmp_v186_zone (code VARCHAR(30) NOT NULL PRIMARY KEY, name VARCHAR(100) NOT NULL, ord INT NOT NULL, is_new BOOLEAN NOT NULL)
    ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

                          created_at, updated_at, deleted, version)
SELECT UNHEX(REPLACE(UUID(), '-', '')), c.company_id, t.code, t.name, 'BOTH', 'Rate zone of the customers'' rate sheets (V186)',
       t.ord, 'ACTIVE', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6), FALSE, 0
FROM tmp_v186_co c
JOIN tmp_v186_zone t ON t.is_new
WHERE NOT EXISTS (SELECT 1 FROM tariff_zones z WHERE z.company_id = c.company_id AND z.code = t.code AND z.deleted = FALSE);

UPDATE tariff_zones z
JOIN tmp_v186_co c ON c.company_id = z.company_id
JOIN tmp_v186_zone t ON t.code = z.code
SET z.display_order = t.ord, z.updated_at = UTC_TIMESTAMP(6)
WHERE z.deleted = FALSE;

-- 3. Places -----------------------------------------------------------------------------------------------
DROP TABLE IF EXISTS tmp_v186_pin;
CREATE TABLE tmp_v186_pin (pincode CHAR(6) NOT NULL PRIMARY KEY, zone_code VARCHAR(30) NOT NULL)
    ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

UPDATE tariff_zone_locations l
JOIN tariff_zones z ON z.id = l.zone_id
JOIN tmp_v186_co c ON c.company_id = z.company_id
SET l.deleted = TRUE, l.deleted_at = UTC_TIMESTAMP(6), l.updated_at = UTC_TIMESTAMP(6)
WHERE l.deleted = FALSE AND (z.code = 'REST_OF_INDIA' OR z.code IN (SELECT code FROM tmp_v186_zone));

DROP TABLE IF EXISTS tmp_v186_place;
CREATE TABLE tmp_v186_place (
    pincode VARCHAR(10) NOT NULL PRIMARY KEY, city_id BINARY(16) NOT NULL, district_id BINARY(16) NULL,
    state_id BINARY(16) NULL, zone_code VARCHAR(30) NULL, KEY (city_id)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;
SELECT p.code, a.city_id, ci.district_id, d.state_id, t.zone_code
FROM master_pincodes p
JOIN master_areas a ON a.id = p.area_id
JOIN master_cities ci ON ci.id = a.city_id
LEFT JOIN master_districts d ON d.id = ci.district_id
LEFT JOIN tmp_v186_pin t ON t.pincode = p.code
WHERE p.company_id = @g AND p.deleted = FALSE AND LENGTH(p.code) = 6;

DROP TABLE IF EXISTS tmp_v186_city;
CREATE TABLE tmp_v186_city (city_id BINARY(16) NOT NULL PRIMARY KEY, zone_code VARCHAR(30) NOT NULL)
    ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;
SELECT city_id, MIN(zone_code) FROM tmp_v186_place GROUP BY city_id
HAVING SUM(zone_code IS NULL) = 0 AND COUNT(DISTINCT zone_code) = 1;

                                   created_at, updated_at, deleted, version)
SELECT UNHEX(REPLACE(UUID(), '-', '')), z.company_id, z.id, 'CITY', d.state_id, ci.district_id, w.city_id, NULL,
       UTC_TIMESTAMP(6), UTC_TIMESTAMP(6), FALSE, 0
FROM tmp_v186_city w
JOIN master_cities ci ON ci.id = w.city_id
LEFT JOIN master_districts d ON d.id = ci.district_id
JOIN tariff_zones z ON z.code = w.zone_code AND z.deleted = FALSE
JOIN tmp_v186_co c ON c.company_id = z.company_id;

                                   created_at, updated_at, deleted, version)
SELECT UNHEX(REPLACE(UUID(), '-', '')), z.company_id, z.id, 'PINCODE', t.state_id, t.district_id, t.city_id, t.pincode,
       UTC_TIMESTAMP(6), UTC_TIMESTAMP(6), FALSE, 0
FROM tmp_v186_place t
JOIN tariff_zones z ON z.code = t.zone_code AND z.deleted = FALSE
JOIN tmp_v186_co c ON c.company_id = z.company_id
WHERE t.zone_code IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM tmp_v186_city w WHERE w.city_id = t.city_id);

-- 4. Rates follow -----------------------------------------------------------------------------------------
DROP TABLE IF EXISTS tmp_v186_copy;
CREATE TABLE tmp_v186_copy (company_id BINARY(16) NOT NULL, from_id BINARY(16) NOT NULL, to_id BINARY(16) NOT NULL,
                            PRIMARY KEY (company_id, from_id, to_id)) ENGINE = InnoDB;
SELECT c.company_id, c.roi_id, z.id FROM tmp_v186_co c
JOIN tariff_zones z ON z.company_id = c.company_id AND z.deleted = FALSE AND z.code IN ('METRO', 'WEST', 'CENTRAL', 'SOUTH', 'NORTH');
SELECT c.company_id, c.ne_id, z.id FROM tmp_v186_co c
JOIN tariff_zones z ON z.company_id = c.company_id AND z.deleted = FALSE AND z.code = 'EAST'
WHERE c.ne_id IS NOT NULL;

                               weight_to_kg, rate_type, rate, step_kg, created_at, updated_at, deleted, version)
SELECT UNHEX(REPLACE(UUID(), '-', '')), s.company_id, s.rate_card_id, m.to_id, s.service_type_id, s.package_type_id,
       s.weight_from_kg, s.weight_to_kg, s.rate_type, s.rate, s.step_kg, UTC_TIMESTAMP(6), UTC_TIMESTAMP(6), FALSE, 0
FROM tariff_rate_slabs s
JOIN tmp_v186_copy m ON m.company_id = s.company_id AND m.from_id = s.to_zone_id
WHERE s.deleted = FALSE;

                                 package_type_id, applies_when, calc_method, charge_value, min_amount, max_amount, taxable,
                                 display_order, status, created_at, updated_at, deleted, version)
SELECT UNHEX(REPLACE(UUID(), '-', '')), r.company_id, r.rate_card_id, r.charge_code, r.charge_name, m.to_id, r.service_type_id,
       r.package_type_id, r.applies_when, r.calc_method, r.charge_value, r.min_amount, r.max_amount, r.taxable,
       r.display_order, r.status, UTC_TIMESTAMP(6), UTC_TIMESTAMP(6), FALSE, 0
FROM tariff_charge_rules r
JOIN tmp_v186_copy m ON m.company_id = r.company_id AND m.from_id = r.to_zone_id
WHERE r.deleted = FALSE;

-- 5. REST_OF_INDIA goes -----------------------------------------------------------------------------------
UPDATE tariff_rate_slabs s JOIN tmp_v186_co c ON c.roi_id = s.to_zone_id
SET s.deleted = TRUE, s.deleted_at = UTC_TIMESTAMP(6), s.updated_at = UTC_TIMESTAMP(6)
WHERE s.deleted = FALSE;
UPDATE tariff_charge_rules r JOIN tmp_v186_co c ON c.roi_id = r.to_zone_id
SET r.deleted = TRUE, r.deleted_at = UTC_TIMESTAMP(6), r.updated_at = UTC_TIMESTAMP(6)
WHERE r.deleted = FALSE;
UPDATE tariff_zones z JOIN tmp_v186_co c ON c.roi_id = z.id
SET z.deleted = TRUE, z.deleted_at = UTC_TIMESTAMP(6), z.updated_at = UTC_TIMESTAMP(6), z.status = 'INACTIVE', z.version = z.version + 1;

UPDATE tariff_zones z JOIN tmp_v186_co c ON c.company_id = z.company_id
SET z.location_count = (SELECT COUNT(*) FROM tariff_zone_locations l WHERE l.zone_id = z.id AND l.deleted = FALSE);

DROP TABLE tmp_v186_copy;
DROP TABLE tmp_v186_city;
DROP TABLE tmp_v186_place;
DROP TABLE tmp_v186_pin;
DROP TABLE tmp_v186_zone;
DROP TABLE tmp_v186_co;
